import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import {
    FormBuilder,
    ReactiveFormsModule,
    Validators
} from '@angular/forms';
import { ActivatedRoute } from '@angular/router';

import { CandidatosService } from '../../services/candidatos.service';
import { VotacoesService } from '../../services/votacoes.service';

import { Votacao } from '../../shared/models';

import { Router } from '@angular/router';

type CategoriaProjeto =
    | 'INOVACAO'
    | 'SOCIAL'
    | 'UNIVERSITARIO';

@Component({
    selector: 'app-candidatos-public',
    standalone: true,
    imports: [
        CommonModule,
        ReactiveFormsModule
    ],
    templateUrl: './candidatos-public.page.html',
    styleUrls: ['./candidatos-public.page.scss']
})
export class CandidatosPublicPageComponent implements OnInit {

    loading = true;
    saving = false;

    error = '';
    success = '';

    votacao: Votacao | null = null;

    votacaoId = 0;

    categoriasProjeto: Array<{
        value: CategoriaProjeto;
        label: string;
    }> = [
            {
                value: 'INOVACAO',
                label: 'Inovação'
            },
            {
                value: 'SOCIAL',
                label: 'Social'
            },
            {
                value: 'UNIVERSITARIO',
                label: 'Universitário'
            }
        ];

    form = this.fb.nonNullable.group({

        nome: [
            '',
            [
                Validators.required,
                Validators.maxLength(200)
            ]
        ],

        descricao: [
            '',
            [
                Validators.required,
                Validators.maxLength(4000)
            ]
        ],

        fotoUrl: [
            '',
            [
                Validators.required,
                Validators.pattern(/^https?:\/\/.+/i)
            ]
        ],

        email: [
            '',
            [
                Validators.required,
                Validators.email,
                Validators.maxLength(200)
            ]
        ],

        telefone: [
            '',
            [
                Validators.required,
                Validators.pattern(
                    /^\(?\d{2}\)?\s?9?\d{4}-?\d{4}$/
                )
            ]
        ],

        empresa: [
            '',
            [
                Validators.required,
                Validators.maxLength(255)
            ]
        ],

        categoriaProjeto: [
            '',
            [Validators.required]
        ],

        nomeProjeto: [
            '',
            [
                Validators.required,
                Validators.maxLength(255)
            ]
        ],

        participantes: [
            '',
            [Validators.maxLength(4000)]
        ],

        periodoExecucao: [
            '',
            [
                Validators.required,
                Validators.maxLength(255)
            ]
        ],

        stakeholders: [
            '',
            [
                Validators.required,
                Validators.maxLength(8000)
            ]
        ],

        orcamento: [
            '',
            [
                Validators.required,
                Validators.maxLength(8000)
            ]
        ],

        ferramentasMetodologias: [
            '',
            [
                Validators.required,
                Validators.maxLength(8000)
            ]
        ],

        resumoProjeto: [
            '',
            [
                Validators.required,
                Validators.maxLength(12000)
            ]
        ],

        solucaoDesenvolvida: [
            '',
            [
                Validators.required,
                Validators.maxLength(12000)
            ]
        ],

        resultadosImpacto: [
            '',
            [
                Validators.required,
                Validators.maxLength(12000)
            ]
        ],

        autorizacaoAudiovisual: [
            false,
            Validators.requiredTrue
        ],

        declaracaoVeracidade: [
            false,
            Validators.requiredTrue
        ]
    });

    constructor(
        private readonly fb: FormBuilder,
        private readonly router: Router,
        private readonly route: ActivatedRoute,
        private readonly votacoesService: VotacoesService,
        private readonly candidatosService: CandidatosService
    ) { }

    ngOnInit(): void {

        const idParam = Number(
            this.route.snapshot.paramMap.get('id')
        );

        if (!idParam || Number.isNaN(idParam)) {

            this.error = 'Votação inválida.';

            this.loading = false;

            return;
        }

        this.votacaoId = idParam;

        this.loadVotacao();
    }

    loadVotacao(): void {

        this.loading = true;

        this.error = '';

        this.votacoesService
            .get(this.votacaoId)
            .subscribe({

                next: (res) => {

                    this.votacao = res;

                    console.log(this.votacao)
                    this.loading = false;
                },

                error: () => {

                    this.loading = false;

                    this.error =
                        'Não foi possível carregar os dados da votação.';
                }
            });
    }

    submit(): void {

        if (this.form.invalid) {

            this.form.markAllAsTouched();

            this.error =
                'Verifique os campos destacados antes de continuar.';

            this.success = '';

            return;
        }

        this.saving = true;

        this.error = '';

        this.success = '';

        const payload = {

            ...this.form.getRawValue(),

            categoriaProjeto:
                this.form.getRawValue()
                    .categoriaProjeto as CategoriaProjeto,

            votacaoId: this.votacaoId
        };

        this.candidatosService
            .create(payload as any)
            .subscribe({

                next: () => {

                    this.saving = false;

                    this.router.navigate([
                        '/inscricao/sucesso'
                        ], {
                        queryParams: {
                            votacao: this.votacao?.nome
                        }
                        });

                    this.form.reset({

                        nome: '',
                        descricao: '',
                        fotoUrl: '',
                        email: '',
                        telefone: '',
                        empresa: '',
                        categoriaProjeto: '',
                        nomeProjeto: '',
                        participantes: '',
                        periodoExecucao: '',
                        stakeholders: '',
                        orcamento: '',
                        ferramentasMetodologias: '',
                        resumoProjeto: '',
                        solucaoDesenvolvida: '',
                        resultadosImpacto: '',
                        autorizacaoAudiovisual: false,
                        declaracaoVeracidade: false
                    });
                },

                error: (err) => {

                    this.saving = false;

                    this.error =
                        err?.error?.message ||
                        'Erro ao enviar cadastro.';
                }
            });
    }

    fieldError(controlName: string): string {

        const control =
            this.form.controls[
            controlName as keyof typeof this.form.controls
            ];

        if (
            !control ||
            !control.touched ||
            !control.errors
        ) {
            return '';
        }

        const errors = control.errors;

        if (errors['required']) {
            return 'Campo obrigatório.';
        }

        if (errors['requiredTrue']) {
            return 'É necessário aceitar esta condição.';
        }

        if (errors['email']) {
            return 'E-mail inválido.';
        }

        if (errors['maxlength']) {
            return `Máximo de ${errors['maxlength'].requiredLength} caracteres.`;
        }

        if (errors['pattern']) {
            return 'Formato inválido.';
        }

        return 'Campo inválido.';
    }
}